// IUPAC complement table (uppercase)
const comp: { [key: string]: string } = {
  'A': 'T', 'C': 'G', 'G': 'C', 'T': 'A', 'U': 'A',
  'R': 'Y', 'Y': 'R', 'K': 'M', 'M': 'K',
  'B': 'V', 'V': 'B', 'D': 'H', 'H': 'D',
