function complementChar(c: string): string {
  const upper = c.toUpperCase();
  const compChar = comp[upper] || upper;
  return c === upper ? compChar : compChar.toLowerCase();
}

function reverseComplement(seq: string): string {
  const len = seq.length;
  const res = new Array<string>(len);
  for (let i = 0; i < len; i++) {
    res[i] = complementChar(seq[len - 1 - i]);
