            for (int i = 0; i < k/2; i++) {
                int t = perm[i]; perm[i] = perm[k-1-i]; perm[k-1-i] = t;
            }
            flipsCount++;
        }

        if (flipsCount > maxFlipsCount) maxFlipsCount = flipsCount;
        checksum += (permCount % 2 == 0) ? flipsCount : -flipsCount;

