  ['c', 0.1979883004921],
  ['g', 0.1975473066391],
  ['t', 0.3015094502008]
];

function buildTable(table: [string, number][]): Uint8Array {
  const cum: number[] = [];
  let sum = 0;
  for (const [_, p] of table) {
    sum += p;
    cum.push(sum);
  }
  const map = new Uint8Array(139968);
  for (let s = 0; s < 139968; s++) {
    const r = s / 139968;
    let i = 0;
    while (i < cum.length && !(cum[i] > r)) i++;
    map[s] = table[i][0].charCodeAt(0);
  }
  return map;
}

