const freqMap = buildTable(FREQ);

const nextSeed = new Uint32Array(139968);
for (let s = 0; s < 139968; s++) {
  nextSeed[s] = (s * 3877 + 29573) % 139968;
}

let seed = 42;

const buf = Buffer.allocUnsafe(1 << 22);
let offset = 0;

function flush() {
  if (offset > 0) {
    let written = 0;
    while (written < offset) {
      written += fs.writeSync(1, buf, written, offset - written);
    }
    offset = 0;
